import Link from "next/link";
import { notFound } from "next/navigation";
import { AdminNav } from "@/components/admin/admin-nav";
import { requireAdmin } from "@/lib/admin/authorization";
import { getPreferences } from "@/lib/i18n/get-translations";
import { getAdminPayment } from "@/lib/payments/service";
import { money, paymentDate, productLabel, statusLabel, statusTone } from "@/lib/payments/admin-display";

export default async function PaymentDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const actor = await requireAdmin("ADMIN_DASHBOARD_READ");
  const prefs = await getPreferences(actor.id), vi = prefs.interfaceLanguage === "vi";
  const data = await getAdminPayment((await params).id);
  if (!data) notFound();
  const { order, membership, events } = data;
  const fields = [[vi?"Mã đơn hàng":"Order code",`TG-${order.orderCode}`],[vi?"Người dùng":"Learner",order.email],[vi?"Gói":"Plan",productLabel(order.productKey,vi)],[vi?"Số tiền":"Amount",money(order.amount,order.currency,prefs.interfaceLanguage)],[vi?"Cổng thanh toán":"Provider",order.provider],[vi?"Ngày tạo":"Created",paymentDate(order.createdAt,prefs.interfaceLanguage)],[vi?"Hết hạn thanh toán":"Payment expires",paymentDate(order.expiresAt,prefs.interfaceLanguage)],[vi?"Thanh toán lúc":"Paid at",paymentDate(order.paidAt,prefs.interfaceLanguage)],[vi?"Hủy lúc":"Cancelled at",paymentDate(order.cancelledAt,prefs.interfaceLanguage)]];
  return <main className="min-h-screen bg-slate-50 px-4 py-6 text-slate-900 sm:px-6"><div className="mx-auto max-w-5xl"><AdminNav locale={prefs.interfaceLanguage}/><Link className="mt-8 inline-block font-bold text-teal-800 underline" href="/admin/payments">← {vi?"Thanh toán":"Payments"}</Link><header className="mt-5"><h1 className="text-3xl font-black">{vi?"Chi tiết đơn hàng":"Order details"}</h1><p className="mt-2 font-mono text-sm text-slate-600">TG-{order.orderCode}</p></header><div className="mt-6 grid gap-5 lg:grid-cols-2"><section className="rounded-2xl border bg-white p-6"><h2 className="text-xl font-bold">{vi?"Thông tin đơn hàng":"Order information"}</h2><p className="mt-4"><span className={`rounded-full px-3 py-1 text-sm font-bold ${statusTone(order.status)}`}>{statusLabel(order.status,vi)}</span></p><dl className="mt-5 grid gap-4">{fields.map(([label,value])=><div className="border-t pt-3" key={label}><dt className="text-sm text-slate-600">{label}</dt><dd className="mt-1 break-all font-semibold">{value}</dd></div>)}</dl></section><div className="space-y-5"><section className="rounded-2xl border bg-white p-6"><h2 className="text-xl font-bold">{vi?"Kết quả Premium":"Premium outcome"}</h2><p className="mt-4 text-sm text-slate-600">{vi?"Thanh toán":"Payment"}</p><p className="font-bold">{statusLabel(order.status,vi)}</p><p className="mt-4 text-sm text-slate-600">{vi?"Quyền Premium":"Premium entitlement"}</p><p className="font-bold">{membership ? membership.revokedAt ? vi?"Đã thu hồi":"Revoked" : vi?"Đã cấp":"Granted" : order.status === "PAID" ? vi?"Chưa tìm thấy bản ghi cấp quyền — cần kiểm tra":"No grant record found — review needed" : vi?"Chưa cấp":"Not granted"}</p>{membership&&<p className="mt-2 text-sm text-slate-600">{paymentDate(membership.startsAt,prefs.interfaceLanguage)} → {paymentDate(membership.endsAt,prefs.interfaceLanguage)}</p>}{order.status!=="PAID"&&<p className="mt-4 rounded-xl bg-slate-100 p-3 text-sm">{vi?"Thanh toán chưa được xác nhận. Kiểm tra trạng thái với cổng thanh toán khi cần hỗ trợ người dùng.":"Payment has not been confirmed. Check the provider status when assisting this learner."}</p>}</section><section className="rounded-2xl border bg-white p-6"><h2 className="text-xl font-bold">{vi?"Chi tiết kỹ thuật":"Technical details"}</h2><dl className="mt-4 space-y-3 text-sm"><div><dt className="text-slate-600">{vi?"ID đơn hàng":"Order ID"}</dt><dd className="break-all font-mono">{order.id}</dd></div><div><dt className="text-slate-600">{vi?"Mã tham chiếu cổng thanh toán":"Provider reference"}</dt><dd className="break-all font-mono">{order.providerPaymentId ? `••••${order.providerPaymentId.slice(-4)}` : "—"}</dd></div></dl><h3 className="mt-6 font-bold">{vi?"Sự kiện xử lý":"Processing events"}</h3>{events.length?<ul className="mt-3 space-y-2 text-sm">{events.map((event,i)=><li className="rounded-lg bg-slate-50 p-3" key={i}>{event.eventType === "PAYMENT_SUCCEEDED" ? vi?"Xác nhận thanh toán":"Payment confirmation" : vi?"Thông báo thanh toán không thành công":"Unsuccessful payment notice"} · {event.processingStatus === "PROCESSED" ? vi?"Đã xử lý":"Processed" : event.processingStatus === "REJECTED" ? vi?"Không được chấp nhận":"Rejected" : vi?"Chưa hoàn tất":"Incomplete"} · {paymentDate(event.receivedAt,prefs.interfaceLanguage)}</li>)}</ul>:<p className="mt-3 text-sm text-slate-600">{vi?"Chưa có sự kiện xử lý.":"No processing events yet."}</p>}</section></div></div></div></main>;
}
